# Hypothesis: a checker should reject passing a keyword-only function where a positional Callable is expected, should accept a function whose extra parameters have defaults, and should keep a ParamSpec-decorated signature intact.
from typing import Callable, Protocol, assert_type, reveal_type


class Formatter(Protocol):
    def __call__(self, value: int, /, *, sep: str = ' ') -> str: ...


def fmt_default(value: int, /, *, sep: str = ' ') -> str:
    return f'{value}{sep}!'


def fmt_plain(value: int) -> str:
    return str(value)


def fmt_kw_only(*, value: int) -> str:
    return str(value)


def apply_fmt(f: Formatter, v: int) -> str:
    return f(v, sep='-')


def take_unary(cb: Callable[[int], str], v: int) -> str:
    return cb(v)


def decorate[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)
    return wrapper


@decorate
def scaled(x: int, factor: int = 2) -> int:
    return x * factor


double: Callable[[int], int] = lambda x: x * 2
bad_cb: Callable[[int], str] = fmt_kw_only  # expect-error
ok_cb: Callable[[int], str] = fmt_default

reveal_type(scaled)
assert_type(scaled(3), int)
assert scaled(3) == 6
assert scaled(3, factor=3) == 9
assert double(5) == 10
assert fmt_kw_only(value=1) == '1'
assert ok_cb(4) == '4 !'
assert apply_fmt(fmt_default, 4) == '4-!'
assert take_unary(fmt_plain, 7) == '7'
assert take_unary(lambda n: f'<{n}>', 8) == '<8>'

try:
    apply_fmt(fmt_plain, 1)  # expect-error
except TypeError:
    plain_rejected = True
else:
    plain_rejected = False
assert plain_rejected
